package com.crm.crm.controller;
import com.crm.crm.entity.*; import com.crm.crm.service.*; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/interactions") public class InteractionController {private final InteractionService s;private final ClientService cs;public InteractionController(InteractionService s,ClientService cs){this.s=s;this.cs=cs;}@GetMapping public String list(Model m){m.addAttribute("interactions",s.findAll());return "interactions/list";}@GetMapping("/new") public String form(Model m){m.addAttribute("interaction",new Interaction());m.addAttribute("clients",cs.findAll());return "interactions/form";}@PostMapping("/save") public String save(@Valid @ModelAttribute Interaction interaction,BindingResult br,@RequestParam(required=false) Long clientId,Model m){if(br.hasErrors()){m.addAttribute("clients",cs.findAll());return "interactions/form";}interaction.setClient(clientId==null?null:cs.findById(clientId).orElse(null));s.save(interaction);return "redirect:/interactions";}@PostMapping("/delete/{id}") public String delete(@PathVariable Long id){s.delete(id);return "redirect:/interactions";}}
